def yq(text):
    """A YAML double-quoted scalar (descriptions hold colons and quotes)."""
    return '"' + text.replace("\\", "\\\\").replace('"', '\\"') + '"'


def stored_block(skill):
    text = (PLUGIN / "skills" / "schedule-workforce" / "references" / "scheduled-prompts.md").read_text()
    for block in re.findall(r"```\n(.*?)```", text, re.S):
        if block.startswith("[AI Workforce task: %s |" % skill):
            return block.replace("<BRAIN>", "Business Brain").strip()
    raise SystemExit("no stored block for " + skill)


