def row(id, title, work_type, status, key, **f):
    parts = [f"id {id}", f"Assignment: {title}", f"Work type: {work_type}", f"Status: {status}", f"Work key: {key}"]
    parts += [f"{k.replace('_', ' ').capitalize()}: {v}" for k, v in f.items()]
    return "- " + " | ".join(parts)


def draft(id, to, subject, thread, reply_to, body):
    return f"Draft {id} | to {to} | subject \"{subject}\" | threadId {thread} | replyToMessageId {reply_to} | no attachments | viewUrl https://mail.example/drafts/{id}\n\"\"\"\n{body}\n\"\"\""


def mailbox(threads, drafts=(), sent_note="Sent mail, last 7 days: nothing other than what the threads below show."):
    out = ["(Test stand-in: every search returns this whole mailbox. Each message shows its labels. No more pages.)", "", sent_note, ""]
    out += threads
    out += ["", "Drafts in this mailbox:"] + (list(drafts) or ["(none)"])
    return "\n".join(out)


def g_regex(pattern, match="contains", target="last_message", flags=None):
    assert "'" not in pattern and "\n" not in pattern, pattern          # written as a one-line YAML single-quoted scalar
    lines = ["type: regex"] + (["target: mock_calls"] if target == "mock_calls" else []) + [f"pattern: '{pattern}'"]
    if flags:
        lines.append(f"flags: {flags}")
    lines.append(f'match: "{match}"' if match.startswith("count") else f"match: {match}")
    return "---\n" + "\n".join(lines) + "\n---\n"


def g_llm(criteria, focus=None):
    return "---\ntype: llm\n" + ("focus: mock_calls\n" if focus == "mock_calls" else "") + "---\n\n" + criteria.strip() + "\n"


def g_skill(names):
    return f"---\ntype: tool_used\ntool: Skill\ninput_match: '{names}'\n---\n"


