# ----------------------------------------------------------------------------------------------------
def files_for(name, c):
    """Every file of one generated case: {relative path: text}."""
    unattended = c.get("unattended", False)
    skills = c["skill"]
    system = SYSTEM.format(extra=(" Google Calendar: list_events()." if c.get("calendar") else "") + c.get("extra_tools", ""),
                           fixed=c.get("fixed", FIXED), clock=c["clock"], tz=TZ, presence=UNATTENDED if unattended else ATTENDED)
    if unattended:
        block = stored_block(skills.split("|")[0])
        if "member" in c:
            block = block.replace("<MEMBER>", c["member"][0]).replace("<RESPONSIBILITY>", c["member"][1])
        prompt = block + c.get("prompt_tail", "")
    else:
        prompt = c["prompt"]
    front = ["---", "description: " + yq(f"{c['description']} ({MARK}; proof list: {c['proof']})"),
             "tags: [mocks, " + ("scheduled" if unattended else "attended") + "]", "max_turns: 40", "timeout_seconds: 900",
             "allowed_tools: [Skill, Read, Glob, Grep]", "append_system_prompt: " + yq(system), "---", "", prompt, ""]
    out = {"prompt.md": "\n".join(front)}
    graders = dict(c["graders"])
    graders["team-rules-loaded"] = g_skill(skills)
    for g, text in graders.items():
        out[f"graders/{g}.md"] = text
    mocks = {"Notion": {"notion-fetch": c["brain"], "notion-search": BRAIN_POINTER, "notion-query-data-sources": BRAIN_POINTER},
             "Gmail": {"search_threads": c["mail"], "get_thread": THREAD_POINTER + c["mail"], "list_drafts": c["mail"], "get_draft": DRAFT_POINTER + c["mail"]}}
    for server, tools in MARKERS.items():
        mocks[server].update(tools)
    if c.get("calendar"):
        mocks["Google_Calendar"] = {"list_events": "(Test stand-in: every call returns the whole calendar.)\n" + c.get("events", "No events.")}
    for server, tools in c.get("more_mocks", {}).items():
        mocks.setdefault(server, {}).update(tools)
    errors = c.get("errors", {})
    for server, tools in errors.items():
        mocks.setdefault(server, {}).update(tools)
    for server, tools in mocks.items():
        for tool, body in tools.items():
            is_error = tool in errors.get(server, {})
            out[f"mocks/{server}/{tool}.md"] = ("---\nerror: true\n---\n\n" if is_error else "") + body.rstrip("\n") + "\n"
    return out


def generated_dirs():
    return sorted(p.parent for p in EVALS.glob("*/prompt.md") if MARK in p.read_text())


def main(check):
    problems = []
    for name, c in CASES.items():
        want, d = files_for(name, c), EVALS / name
        have = {str(p.relative_to(d)) for p in d.rglob("*") if p.is_file()} if d.exists() else set()
        if set(want) != have or any((d / rel).read_text() != text for rel, text in want.items()):
            problems.append(name)
            if not check:
                if d.exists():
                    shutil.rmtree(d)
                for rel, text in want.items():
                    (d / rel).parent.mkdir(parents=True, exist_ok=True)
                    (d / rel).write_text(text)
    for d in generated_dirs():
        if d.name not in CASES:
            problems.append(d.name + " (stray)")
            if not check:
                shutil.rmtree(d)
    if check:
        print("\n".join("stale or missing: " + p for p in problems) or f"All {len(CASES)} generated eval cases are in sync.")
        sys.exit(1 if problems else 0)
    print(f"Wrote {len(problems)} case(s); {len(CASES)} generated cases in total.")


if __name__ == "__main__":
    main("--check" in sys.argv)
